INSERT INTO vg_places(slug,name,category,district,address,excerpt,content,image_url,image_credit,latitude,longitude,source_url,status) VALUES
('gunung-papandayan','Gunung Papandayan','wisata','Cisurupan','Kawasan Gunung Papandayan, Cisurupan, Garut','Lanskap kawah, hutan mati, dan perbukitan untuk perjalanan alam di Cisurupan.',E'Gunung Papandayan adalah destinasi wisata alam di wilayah Cisurupan, Garut. Kawasan ini dikenal melalui lanskap vulkanik dan beberapa area trekking.\n\n## Mengenal kawasan\n\nIndonesia Travel memperkenalkan kawah, Hutan Mati, dan Pondok Saladah sebagai bagian dari pengalaman Papandayan. Pilih jalur dan aktivitas sesuai kemampuan serta informasi pengelola pada hari kunjungan.\n\n## Persiapan berkunjung\n\nSiapkan alas kaki untuk berjalan, perlengkapan pribadi, dan waktu perjalanan yang cukup. Konfirmasi akses kawasan, tiket, serta ketentuan kunjungan sebelum berangkat. Titik pada peta VisitGarut merupakan perkiraan kawasan dan bukan petunjuk pintu masuk.','/papandayan.jpg','Tantan Nurdiansyah / Wikimedia Commons · CC BY-SA 4.0 · ukuran diperkecil',-7.310292,107.725075,'https://www.indonesia.travel/id/id/destination/java/west-java/gunung-papandayan','published'),
('situ-bagendit','Situ Bagendit','wisata','Banyuresmi','Sukamukti, Banyuresmi, Garut','Wisata danau di Banyuresmi dengan panorama air dan latar pegunungan.',E'Situ Bagendit adalah danau di wilayah Banyuresmi, Garut. Destinasi ini menawarkan pengalaman rekreasi tepi danau dan memiliki hubungan dengan cerita rakyat Nyi Endit.\n\n## Mengenal kawasan\n\nIndonesia Travel mencatat adanya kegiatan rekreasi air serta area kuliner di kawasan danau. Ketersediaan aktivitas mengikuti kondisi lapangan dan operasional pengelola.\n\n## Merencanakan kunjungan\n\nPeriksa rute, prakiraan cuaca, serta jam operasional sebelum berangkat. Untuk aktivitas di air, konfirmasi ketentuan dan fasilitas kepada penyedia setempat. Foto yang ditampilkan merupakan dokumentasi tahun 2007; tampilan kawasan saat ini dapat berbeda.','/situ-bagendit.jpg','Edi Wibowo / Wikimedia Commons · CC BY-SA 3.0 · foto 2007',-7.158,107.98,'https://www.indonesia.travel/id/id/travel-ideas/adventure/situ-bagendit','published'),
('talaga-bodas','Talaga Bodas','wisata','Wanaraja','Sukamenak, Wanaraja, Garut','Danau kawah dengan lanskap putih di kawasan dataran tinggi Wanaraja.',E'Talaga Bodas berada di kawasan Wanaraja, Garut. Danau kawah ini menjadi salah satu pilihan perjalanan alam di dataran tinggi.\n\n## Mengenal kawasan\n\nPemerintah Kabupaten Garut memperkenalkan Talaga Bodas sebagai taman wisata alam dengan daya tarik danau putih. Foto di halaman ini memperlihatkan kawasan danau dari Gunung Sagara.\n\n## Merencanakan kunjungan\n\nPeriksa kondisi akses dan ketentuan kunjungan kepada pengelola sebelum berangkat. Sediakan waktu perjalanan yang cukup dan ikuti batas area yang berlaku di lokasi. Titik pada peta merupakan perkiraan kawasan.','/talaga-bodas.jpg','Rangga Prawira / Wikimedia Commons · CC BY-SA 4.0 · ukuran diperkecil',-7.208,108.069,'https://www.garutkab.go.id/berita/pantau-twa-talaga-bodas-bupati-garut-ajak-wisatawan-nikmati-keindahan-danau-putih-dan-khasiat-air-belerang','published')
INSERT INTO vg_articles(slug,title,excerpt,content,author,status,published_at) VALUES
('mulai-jelajahi-garut','Mulai jelajahi Garut: memilih tempat untuk perjalanan pertama','Kenali tiga pilihan wisata alam dan susun perjalanan berdasarkan wilayah serta aktivitas yang kamu inginkan.',E'Memilih tempat untuk perjalanan pertama ke Garut bisa dimulai dari aktivitas yang ingin kamu lakukan. Direktori VisitGarut memperkenalkan beberapa pilihan wisata alam, lalu menghubungkannya dengan halaman tempat yang dapat dibaca lebih lanjut.\n\n## Untuk pengalaman pegunungan: Papandayan\n\nPapandayan berada di wilayah Cisurupan. Kawasan vulkanik ini memiliki pengalaman trekking dan lanskap kawah. Baca halaman Gunung Papandayan untuk mengetahui gambaran kawasan dan sumber informasi kunjungannya.\n\n## Untuk rekreasi danau: Situ Bagendit\n\nSitu Bagendit berada di Banyuresmi. Jika ingin memulai dari suasana tepi danau, tempat ini dapat dimasukkan ke daftar pilihan. Pastikan kegiatan yang kamu inginkan tersedia ketika berkunjung.\n\n## Untuk lanskap danau kawah: Talaga Bodas\n\nTalaga Bodas berada di kawasan Wanaraja. Destinasi ini menawarkan sudut Garut yang berbeda dari Cisurupan dan Banyuresmi. Periksa lokasi pada peta, kemudian cek akses menuju kawasan sebelum memasukkannya ke rencana perjalanan.\n\n## Susun berdasarkan wilayah\n\nGunakan peta untuk melihat hubungan antarlokasi. Hindari menjadikan jumlah tempat sebagai satu-satunya target perjalanan. Sisakan waktu untuk perjalanan, istirahat, dan perubahan rencana.\n\n## Konfirmasi sebelum berangkat\n\nInformasi tiket, jam buka, dan akses bisa berubah. Gunakan tautan sumber pada halaman tempat untuk memulai pengecekan, lalu konfirmasikan informasi operasional kepada pengelola.','Tim VisitGarut','published',now()),
('merencanakan-perjalanan-garut','Merencanakan perjalanan Garut dengan peta dan direktori','Cara memakai kategori, pencarian wilayah, dan peta untuk menyusun pilihan tempat di Garut.',E'Rencana perjalanan yang nyaman dimulai dari memilih tempat, memahami lokasinya, dan menentukan waktu yang tersedia. Kamu bisa menggunakan direktori VisitGarut untuk mengumpulkan informasi tersebut.\n\n## Mulai dari kategori\n\nBuka kategori Wisata untuk melihat tempat yang sudah masuk dalam direktori. Kategori hotel, kuliner, cafe, transportasi, dan paket wisata akan bertambah ketika informasi penyedia tersedia.\n\n## Cari nama tempat atau wilayah\n\nPencarian dapat digunakan untuk menemukan nama tempat dan kecamatan. Gunakan filter wilayah jika sudah menentukan area yang ingin dikunjungi. Jika tidak menemukan hasil, coba kata yang lebih singkat atau lihat semua tempat.\n\n## Bandingkan lokasi pada peta\n\nPeta membantu melihat posisi kawasan. Klik titik atau nama tempat untuk membuka halaman detail. Koordinat yang belum dikonfirmasi sebagai pintu masuk hanya digunakan sebagai gambaran lokasi. Untuk menuju tempat, gunakan pencarian rute pada halaman detail dan periksa ulang tujuanmu.\n\n## Baca sumber dan simpan pilihan\n\nSetiap halaman tempat mencantumkan sumber informasi ketika tersedia. Baca gambaran tempat dan sumbernya sebelum menentukan pilihan. Catat daftar tempat di perangkatmu; fitur akun dan wishlist belum menjadi bagian versi awal ini.\n\n## Lengkapi rencana dengan konfirmasi\n\nHubungi pengelola untuk mengecek tiket, operasional, dan ketersediaan aktivitas. Sesuaikan rencana dengan cuaca, kendaraan, serta kebutuhan anggota perjalanan.','Tim VisitGarut','published',now())
INSERT INTO vg_article_places(article_id,place_id) SELECT a.id,p.id FROM vg_articles a CROSS JOIN vg_places p WHERE a.slug='mulai-jelajahi-garut' AND p.slug IN ('gunung-papandayan','situ-bagendit','talaga-bodas') ON CONFLICT DO NOTHING;
INSERT INTO vg_places(slug,name,category,district,address,excerpt,content,website,whatsapp,source_url,status) VALUES
('kampung-sampireun','Kampung Sampireun Resort & Spa','hotel','Samarang','Jl. Raya Kamojang KM 4, Sukakarya, Samarang, Garut','Resor dengan suasana danau dan arsitektur yang terinspirasi budaya Sunda.',E'Kampung Sampireun adalah akomodasi resor di kawasan Samarang, Garut. Situs resminya memperkenalkan konsep budaya Sunda dan pilihan cottage serta bungalow.\n\n## Informasi dari pengelola\n\nUntuk tipe kamar, fasilitas, dan ketersediaan tanggal, gunakan situs resmi atau hubungi front office. VisitGarut menyediakan informasi direktori dan tidak menerima pembayaran reservasi.\n\n## Merencanakan menginap\n\nPastikan jumlah tamu, tanggal, kebijakan kamar, serta layanan yang termasuk dalam penawaran sebelum membuat reservasi dengan penyedia.','https://kampungsampireun.com/','6281323007130','https://kampungsampireun.com/','published'),
('bale-tingtrim-resto','Bale Tingtrim Resto','kuliner','Tarogong Kaler','Jl. Otto Iskandardinata No. 64, Cimanganten, Tarogong Kaler, Garut','Tempat makan di Tarogong Kaler dengan sajian khas Sunda.',E'Bale Tingtrim Resto berada di Jalan Otto Iskandardinata, Tarogong Kaler, Garut. Website resminya memperkenalkan hidangan khas Sunda dan layanan untuk kegiatan bersama.\n\n## Sebelum berkunjung\n\nLihat menu serta informasi operasional melalui website pengelola. Untuk kunjungan rombongan, tanyakan kapasitas dan pilihan menu sebelum menentukan waktu kedatangan.','https://www.baletingtrimresto.com/','6281399889023','https://www.baletingtrimresto.com/','published'),
('qq-cafe-garut','QQ Cafe Garut','cafe','Tarogong Kaler','Jl. Cipanas Baru No. 48, Pananjung, Tarogong Kaler, Garut','Cafe di kawasan Cipanas Baru, Tarogong Kaler.',E'QQ Cafe Garut mencantumkan lokasi di Jalan Cipanas Baru No. 48 melalui halaman resmi Linktree miliknya. Halaman tersebut menyediakan tautan Instagram, menu cafe, dan petunjuk lokasi.\n\n## Sebelum berkunjung\n\nGunakan halaman resmi untuk melihat informasi menu dan konfirmasi operasional terkini. Foto serta koordinat cafe belum tersedia dalam direktori VisitGarut.','https://linktr.ee/qqcafegarut','','https://linktr.ee/qqcafegarut','published')
